import { logDevReady } from "@remix-run/cloudflare";
import { createPagesFunctionHandler } from "@remix-run/cloudflare-pages";
import type { ServerBuild } from "@remix-run/cloudflare";
import * as devBuild from "@remix-run/dev/server-build";

// @remix-run/dev/server-build's declarations predate ServerBuild.isSpaMode,
// which the real build (generated by `remix build`) does export.
const build = devBuild as unknown as ServerBuild;

if (process.env.NODE_ENV === "development") {
  logDevReady(build);
}

export const onRequest = createPagesFunctionHandler({
  build,
  getLoadContext: (context) => ({ env: context.env }),
  mode: build.mode,
});
